// /frontend-react/src/components/MedicalDashboard.js

import React from 'react';
import HeaderBar from './HeaderBar'; // Correctly imported

// --- Local Date Logic for Blinking ---
// NOTE: These dates are mocked for demonstration purposes.
// Mock Appointment Date (Dec 10th)
const APPOINTMENT_DATE_STRING = '2025-12-10T10:00:00'; 
const APPOINTMENT_DATE = new Date(APPOINTMENT_DATE_STRING);

// Mock Today's Date: Set to December 8th (2 days before appointment) to trigger the blinking.
// Change this date to a date outside the 3-day window (e.g., '2025-12-05') to test the non-blinking state.
const MOCK_TODAY = new Date('2025-12-08'); 

// Calculate days difference (ensures we get a full day count)
const MS_PER_DAY = 1000 * 60 * 60 * 24;
const timeDiff = APPOINTMENT_DATE.getTime() - MOCK_TODAY.getTime();
const daysDiff = Math.ceil(timeDiff / MS_PER_DAY);

// Condition: Is the appointment today (0) or in the next 3 days?
const isAppointmentSoon = daysDiff >= 0 && daysDiff <= 3;
// --- End Local Date Logic ---


const SubIcon = ({ name, emoji, goToPage, pageTarget, isEasyMode, isBlinking }) => {

    const blinkStyle = isBlinking ? {
        // Red color for the alert
        border: '5px solid red', 
        backgroundColor: '#FFE5E5', 
        boxShadow: '0 0 25px rgba(255, 0, 0, 0.7)', 
        transform: 'scale(1.03)',
        // Apply a gentle animation
        animation: 'alert-pulse 1.5s infinite',
    } : {};

    return (
        <div 
            onClick={() => goToPage(pageTarget)}
            style={{
                padding: '15px',
                margin: '15px 15%', 
                borderRadius: '15px',
                width: '70%', 
                textAlign: 'center',
                backgroundColor: '#fff', 
                border: '1px solid #ddd', 
                boxShadow: '0 4px 10px rgba(0,0,0,0.1)', 
                cursor: 'pointer',
                transition: 'all 0.3s', 
                overflow: 'hidden',
                ...blinkStyle // Apply conditional blinking style
            }}
        >
            {/* Top Section: Emoji */}
            <div style={{ paddingBottom: '10px', borderBottom: '2px solid #007bff20' }}>
                 <span role="img" aria-label={name} style={{
                    fontSize: isEasyMode ? '70px' : '45px', 
                    display: 'block', 
                    marginBottom: '5px'
                }}>{emoji}</span>
            </div>

            {/* Bottom Section: Label/Action */}
            <div style={{ 
                 paddingTop: '10px',
                 backgroundColor: isBlinking ? 'red' : '#1A73E8', // Change bar color to red when blinking
                 margin: '-15px', 
                 marginTop: '10px'
            }}>
                <p style={{
                    fontWeight: 'bold', 
                    fontSize: isEasyMode ? '24px' : '18px', 
                    color: 'white', 
                    margin: '0',
                    padding: '10px'
                }}>{name}</p>
            </div>

            {/* CSS Keyframe for the Blinking effect (must be defined or imported globally) */}
            {isBlinking && (
                <style jsx>{`
                    @keyframes alert-pulse {
                        0% { opacity: 1; }
                        50% { opacity: 0.7; }
                        100% { opacity: 1; }
                    }
                `}</style>
            )}
        </div>
    );
};

function MedicalDashboard({ isEasyMode, goToPage, onMenuClick }) {
    return (
        <div style={{ position: 'relative', minHeight: '400px', paddingBottom: '20px' }}>
            
            {/* CORRECT HEADER BAR IMPLEMENTATION */}
            <HeaderBar
                title="Medical Menu"
                onBackClick={() => goToPage('dashboard')} // Goes back to the 4-icon dashboard
                onMenuClick={onMenuClick} // Opens the Side Menu
                isEasyMode={isEasyMode}
            />
            
            {/* The main content area starts below the header */}
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', paddingTop: '15px' }}>
                <SubIcon 
                    name="Appointments" 
                    emoji="🗓️" 
                    pageTarget="appointment" 
                    goToPage={goToPage} 
                    isEasyMode={isEasyMode}
                    isBlinking={isAppointmentSoon}
                />
                <SubIcon name="Transportation" emoji="🚑" pageTarget="transport" goToPage={goToPage} isEasyMode={isEasyMode}/>
                <SubIcon name="Medicine" emoji="💊" pageTarget="medicine" goToPage={goToPage} isEasyMode={isEasyMode}/>
            </div>
        </div>
    );
}

export default MedicalDashboard;
